def find_path(graph,start,goal):
    visited = set() 
    if goal in graph: 
        return [start,goal] 
    if start not in graph: 
        return None 
    for neighbour in graph[start]: 
        if neighbour not in visited: 
            visited.add(neighbour) 
            path = find_path(graph, neighbour, goal) 
            if path: 
                return [start] + path 
    return None

